import { test, expect } from '@playwright/test';

test('Alan completes Flaky Tests and scores 3 / 3', async ({ page, request }) => {
  await request.post('http://localhost:3180/api/_reset');

  await page.goto('http://localhost:5180/#/student/s2');

  const studentSelect = page.getByTestId('student-select');
  await expect(studentSelect).toBeVisible();

  await page.getByTestId('open-assignment-a3').click();

  const quizTitle = page.getByTestId('quiz-title');
  await expect(quizTitle).toHaveText('Flaky Tests');

  await page.locator('.quiz .question:nth-child(1) input[type="radio"]').nth(1).check();
  await page.locator('.quiz .question:nth-child(2) input[type="radio"]').nth(1).check();
  await page.locator('.quiz .question:nth-child(3) input[type="radio"]').nth(1).check();

  const submitButton = page.getByTestId('submit-quiz');
  await expect(submitButton).toBeEnabled();
  await submitButton.click();

  await page.waitForTimeout(2000);
  await page.waitForLoadState('networkidle');

  const resultScore = page.getByTestId('result-score');
  await expect(resultScore).toHaveText('3 / 3');
});

